    return catalog


def alternatives(clause, catalog, forbidden):
    available = []
    for name in clause:
        if name in catalog and name not in forbidden:
            available.append(name)
    return sorted(set(available), key=lambda name: (catalog[name]["cost"], name))


def check_requirements(selected, package, catalog):
    for clause in package["requires"]:
        if not clause:
            return False
        if any(name not in selected for name in clause):
            return False
    return True


def check_conflicts(selected, package, catalog):
    for conflict in package["conflicts"]:
        if conflict in selected:
            return False
    return True


def is_valid(selected, catalog, installed, forbidden):
    for name in selected:
        if name not in catalog:
            return False
        if name in forbidden:
            return False
        package = catalog[name]
        if not check_requirements(selected, package, catalog):
            return False
        if not check_conflicts(selected, package, catalog):
            return False
    return True


def solve(data):
    catalog = make_catalog(data["packages"])
    installed = set(data["installed"])
    forbidden = set(data["forbidden"])
    requested = set(data["requested"])

    for name in installed:
        if name not in catalog or name in forbidden:
            return {"status": "impossible"}

    for name in requested:
        if name not in catalog or name in forbidden:
            return {"status": "impossible"}

    if not is_valid(installed, catalog, installed, forbidden):
        return {"status": "impossible"}

    best_plan = None
    best_cost = None
    best_added = None
    best_selected = None

    def search(selected, added_list):
        nonlocal best_plan, best_cost, best_added, best_selected

        if not is_valid(selected, catalog, installed, forbidden):
            return

        current_cost = sum(catalog[name]["cost"] for name in selected if name not in installed)
        current_added = sorted([name for name in selected if name not in installed])

        if best_plan is None:
            best_plan = selected.copy()
            best_cost = current_cost
            best_added = current_added
            best_selected = selected.copy()
        else:
            if current_cost < best_cost:
                best_plan = selected.copy()
                best_cost = current_cost
                best_added = current_added
                best_selected = selected.copy()
            elif current_cost == best_cost:
                if len(current_added) < len(best_added):
                    best_plan = selected.copy()
                    best_cost = current_cost
                    best_added = current_added
                    best_selected = selected.copy()
                elif len(current_added) == len(best_added):
                    if current_added < best_added:
                        best_plan = selected.copy()
                        best_cost = current_cost
                        best_added = current_added
                        best_selected = selected.copy()

        if not selected:
            return

        for name in catalog:
            if name in selected:
                continue
            if name in installed:
                continue
            if name in forbidden:
                continue

            new_selected = selected.copy()
            new_selected.add(name)
            search(new_selected, added_list + [name])

    search(installed, [])

    if best_plan is None:
        return {"status": "impossible"}

    return {
        "status": "ok",
        "cost": best_cost,
        "added": best_added,
        "selected": sorted(best_selected)
    }
